"""Review remaining independent VI holds; retain the exact earlier auxiliary bank."""
from pathlib import Path
import json,hashlib
P=Path(__file__).resolve().parents[1]/'content/sources/wrk_voltaire_micromegas'
read=lambda f:json.loads((P/f).read_text())
digest=lambda f:hashlib.sha256((P/f).read_bytes()).hexdigest()
h=lambda v:hashlib.sha256(json.dumps(v,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
def write(f,d):(P/f).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
first=read('chapter-06-context-review-01.json');prior='chapter-06-held-context-review-02.json';record=read(prior)
progress=read('chapter-06-progress.json');key=lambda o:(o['unit'],o['start'],o['end'])
origins=[read(a['reviewFile'])for a in progress['continuationPackages']]
available={key(r['sourceOccurrence'])for v in [progress['expressionOverlay'],*[a['expressionOverlay']for a in progress['continuationPackages']]]for r in v['remaining']}
record.update(supersedesFile=prior,supersedesSha256=digest(prior),additionalOriginalReviews=[{'file':'chapter-06-context-review-02.json','sha256':digest('chapter-06-context-review-02.json')}],status='offline_earlier_hold_context_and_questions_reviewed_unpublished')
def bank(form,lemma,pos,meaning,target,low,middle,choices,advanced,note):
 uses=[o for original in [first,*origins]for row in original['holds']if row['form']==form for o in row['sourceOccurrences']if key(o)in available]
 assert uses
 qs=[{'band':'1-3','context':uses[0]['context'],'targetText':uses[0]['text'],'question':'What does the highlighted word mean here?','answer':meaning,'choices':[meaning,*low]},{'band':'4-5','context':middle,'question':'Complétez la phrase.','answer':form,'choices':choices},{'band':'6-8','context':advanced,'question':'Quel mot convient ?','answer':form,'choices':choices}]
 record['items'].append({'key':form.replace('’','_')+'_held_chapter_06_03','form':form,'lemma':lemma,'partOfSpeech':pos,'meaning':meaning,'target':target,'sourceOccurrences':uses,'questions':qs,'questionSha256':h(qs),'sourceOccurrencesSha256':h(uses),'reviewNote':note,'status':'offline_contextual_three_band_review_recorded_unpublished'})
bank('qu’auraient','avoir','fused interrogative plus lexical verb conditional plural','what would they have; what would be available to them','sns_parure_avoir_etre_en_relation_possessive_soit_concrete_ou_abstraite_soit_permanente_ou_occasionnelle_dont_le_possesseur_est_le_sujet_et_le_possede_est_le_complement_d_objet_direct_787c8db8b0',['what would they buy','what would they lose','what would they make'],'Il demande ce que ces êtres auraient à leur disposition : « ___-ils ? »',['qu’auraient','qu’achèteraient','que perdraient','que fabriqueraient'],'Quel groupe interrogatif réunit que et avoir lexical au conditionnel pluriel pour demander de quoi ils disposeraient ?','Qu’auraient-ils à dire asks what content the creatures would have available to say. The published qu’aurait bank is explicitly compound-tense auxiliary, qu’as asks about illness or possession, and the earlier qu’ai à faire de bank tests relationship; all were inspected and excluded as question banks. The global lexical avoir sense explicitly covers abstract as well as concrete possession, so this surface targets that existing sense under lem_avoir. The fused spelling does not create a tense-only sense or another lemma; que stays inside the exact token, and final import must not duplicate an interrogative component encounter. All middle prefixes form grammatical plural hypothetical questions, distinguished by have/buy/lose/make semantics. No earlier mastery is copied.')
bank('comment','comment','interrogative adverb','how; in what way','sns_zola_comment_how',['when','where','why'],'Il interroge la manière dont ces êtres pourraient parler : « ___ le pourraient-ils ? »',['comment','quand','où','pourquoi'],'Quel adverbe interrogatif demande de quelle manière une action serait possible ?','The dwarf asks how the tiny beings could have vocal organs. The existing how sense and all three published banks were inspected; their answer capitalization Comment does not match this source’s interior lowercase surface. Add a lowercase contextual bank on the same meaning, rather than inventing a case-only sense or mutating the earlier sentence-initial bank. All four middle question adverbs are grammatical, while manner rather than time, location or cause selects comment; final surface normalization must preserve existing how mastery.')
bank('en','en','anaphoric pronoun passive-agent reference','by them; referring back to the mites','sns_fr_en_pronominal_reference',['in that place','some of them','from that place'],'Dans « sans en être entendue », les mites seraient celles qui entendent. Le pronom qui reprend cet agent est ___.',['en','elle','ils','on'],'Quel pronom du passage reprend les mites comme agent de être entendue, équivalant ici à d’elles ou par elles ?','Sans en être entendue means without the voice being heard by the mites. The proper published French en pronoun sense already reprises a de complement, independently of the preposition or gerund lemmas. OQLF supports en referring to a de complement including an animal/person, and supports de as a passive-participle complement introducer; the precise historical agent reading in this sentence is an explicit contextual inference from voix and mites, not a verbatim quotation from those pages. Add this contextual bank on the existing de-reference sense, without creating an agent-only duplicate or copying mastery from prepositional en. The middle question names the source pronoun so alternatives remain grammatical labels and the reference role selects en.')
bank('pour','pour','preposition relational analogy','in relation to; relative to','new:lem_pour',['against','without','in the home of'],'Ces êtres sont aux abeilles ce que les abeilles sont à l’homme : ils représentent ___ les abeilles ce que celles-ci représentent pour l’homme.',['pour','contre','sans','chez'],'Quelle préposition met deux êtres en rapport dans une analogie de leurs tailles respectives ?','The four pour occurrences at unit 167 relate scales: small animals to bees, bees to humankind, the Sirian to vast animals, and those vast animals to still larger substances. The global published pour has only beneficiary/purpose questions and the earlier pour moi bank marks personal viewpoint; neither tests this relational analogy. Prepare relational correspondence under the existing French preposition lemma, without a new comparison-only lemma. All alternatives fit the grammatical prepositional slot; correspondence rather than opposition, absence or location selects pour. No published bank is changed; final reconciliation must compare this proposed relation sense with every other workwide pour context before import.')
record['summary']={'resolvedHeldUses':sum(len(i['sourceOccurrences'])for i in record['items']),'contextualProposals':len(record['items']),'newQuestionBands':len(record['items'])*3,'reviewedRouteGroups':len(record['items'])}
file='chapter-06-held-context-review-03.json';write(file,record)
p=read('chapter-06-progress.json');p['heldContextOverlay']={'file':file,'sha256':digest(file),'summary':record['summary']};p['evidenceSha256'][file]=digest(file)
for f in ['chapter-06-lemma-search-05.json','chapter-06-held-lexical-evidence-03.json']:
 p['evidenceSha256'][f]=digest(f)
write('chapter-06-progress.json',p)
print(json.dumps(record['summary']))
